-- Complemento do histórico do Google Forms: QUEM foi o mentor de cada avaliação antiga (planilha "mentorei_avaliacoes_por_mentor",
-- 2.317 avaliações de 02/2025 a 10/2026, com 2.337 notas de mentor). Na importação de 12/10 (4.197 respostas do Forms) as respostas
-- antigas entraram sem mentor; agora cada uma ganha o(s) mentor(es) e a nota de didática vira a nota dele(a) em Gestão › Avaliações › Por mentor.
-- Como liga: cada linha da planilha é achada pelo horário exato da resposta (até o segundo) e, se houver duas no mesmo segundo,
-- pela nota de didática. Nada é apagado nem mudado nas notas que já estavam lá; só se acrescenta o mentor.
--   - Mentor que tem cadastro na plataforma (Cláudia, Viviane, Isaac, Juliana; "Lu" = a mentora "Lu…" que atende o André Decker
--     da Brasdiesel): ganha a nota de mentor (didática de 1 a 10 vira 1 a 5, arredondando para cima, como no histórico).
--   - Quem não tem cadastro (Vanessa, Carla, Rúbia, Renato, Maria, Juliano, Marcos, Vitor, Paula...): fica pelo nome e aparece em
--     "Por mentor" do mesmo jeito (marcado "sem cadastro").
--   - "Ju Vivi" = Juliana e Viviane. Linhas "Provável" entram, com a marca de confiança guardada.
--   - Respostas da planilha mais novas que a última já importada (de 16/10 em diante: Brasdiesel, Cooprem, Cresol Conexão) não estavam
--     na plataforma: entram como avaliações novas do Google Forms (sem módulo), já com o mentor.
-- Se a ligação falhar para muitas linhas (mais de 10% das que deviam estar lá), NADA é gravado e aparece um aviso.
-- Rodar uma vez: SQL Editor → New query → colar tudo → Run. Pode rodar de novo: não repete nada.

do $$
declare
  v_tz text; n_sp int; n_utc int; v_ult text; n_antes int; n_ligadas int; n_novas int; n_notas int;
begin
  drop table if exists pl_mentores;
  create temp table pl_mentores (id text primary key, ts text, cliente text, programa text, data_evento text,
    rel int, did int, mat int, conh int, rec int, mentores jsonb, aval uuid) on commit drop;

  -- as respostas do Forms que já estão na plataforma (menos as que esta planilha criou numa vez anterior),
  -- com o horário nos dois jeitos possíveis (Brasília ou UTC)
  drop table if exists pl_forms;
  create temp table pl_forms on commit drop as
    select a.id, to_char(a.criado_em at time zone 'America/Sao_Paulo', 'YYYY-MM-DD HH24:MI:SS') as ts_sp,
           to_char(a.criado_em at time zone 'UTC', 'YYYY-MM-DD HH24:MI:SS') as ts_utc,
           case when a.extras->'escala_antiga'->>'didatica' ~ '^[0-9]+(\.[0-9]+)?$' then round((a.extras->'escala_antiga'->>'didatica')::numeric)::int end as did,
           null::text as ts
      from avaliacoes a where a.origem = 'google_forms' and not (a.extras ? 'id_planilha');
  select count(*) into n_sp from pl_mentores p where exists (select 1 from pl_forms f where f.ts_sp = p.ts);
  select count(*) into n_utc from pl_mentores p where exists (select 1 from pl_forms f where f.ts_utc = p.ts);
  v_tz := case when n_utc > n_sp then 'UTC' else 'Brasília' end;
  update pl_forms set ts = case when v_tz = 'UTC' then ts_utc else ts_sp end;
  create index on pl_forms (ts);
  select max(ts) into v_ult from pl_forms;

  -- 1ª volta: mesmo segundo e mesma nota de didática (se houver várias iguais, uma com uma, pela ordem)
  update pl_mentores p set aval = x.aid from (
    select pp.id as pid, ff.id as aid from
      (select id, ts, did, row_number() over (partition by ts, did order by id) as n from pl_mentores where aval is null) pp
      join (select id, ts, did, row_number() over (partition by ts, did order by id) as n from pl_forms) ff
        on ff.ts = pp.ts and ff.did = pp.did and ff.n = pp.n) x
   where p.id = x.pid;
  -- 2ª volta: as que sobraram, só pelo segundo
  update pl_mentores p set aval = x.aid from (
    select pp.id as pid, ff.id as aid from
      (select id, ts, row_number() over (partition by ts order by id) as n from pl_mentores where aval is null) pp
      join (select f.id, f.ts, row_number() over (partition by f.ts order by f.id) as n from pl_forms f
             where not exists (select 1 from pl_mentores q where q.aval = f.id)) ff
        on ff.ts = pp.ts and ff.n = pp.n) x
   where p.id = x.pid;

  select count(*) into n_antes from pl_mentores where ts <= coalesce(v_ult, '');
  select count(*) into n_ligadas from pl_mentores where aval is not null;
  if n_antes > 0 and n_ligadas < n_antes * 0.9 then
    raise exception 'Só achei % das % avaliações da planilha que deviam estar na plataforma. Nada foi gravado: mande um print para o Claude.', n_ligadas, n_antes;
  end if;

  -- as que esta planilha já criou numa vez anterior
  update pl_mentores p set aval = a.id from avaliacoes a
   where p.aval is null and a.origem = 'google_forms' and a.extras->>'id_planilha' = p.id;

  -- as mais novas que a última importada entram como avaliações novas do Google Forms
  with novas as (
    select 'google_forms', p.cliente || ' · ' || p.programa,
           case when p.rel is not null then least(5, greatest(1, ceil(p.rel / 2.0)))::int end,
           case when p.mat is not null then least(5, greatest(1, ceil(p.mat / 2.0)))::int end,
           case when p.rec is null then null when p.rec > 5 then p.rec else p.rec * 2 end,
           jsonb_build_object('escala_antiga', jsonb_strip_nulls(jsonb_build_object('relevancia', p.rel, 'didatica', p.did, 'materiais', p.mat,
             'conhecimento_depois', p.conh, 'recomendacao', p.rec)), 'chave', md5('planilha-mentores:' || p.id), 'id_planilha', p.id),
           (p.ts::timestamp at time zone 'America/Sao_Paulo')
      from pl_mentores p
     where p.aval is null and p.ts > coalesce(v_ult, '')
    returning id, extras->>'id_planilha' as id_planilha)
  update pl_mentores p set aval = novas.id from novas where novas.id_planilha = p.id;
  get diagnostics n_novas = row_count;

  -- quem tem cadastro: o mesmo primeiro nome entre mentores e administração que atende (só se for uma pessoa só)
  drop table if exists pl_mapa;
  create temp table pl_mapa on commit drop as
    select x.nome, case when count(pf.id) = 1 then (array_agg(pf.id))[1] end as perfil_id
      from (select distinct m->>'nome' as nome from pl_mentores, jsonb_array_elements(mentores) m) x
      left join perfis pf on (pf.papel = 'mentor' or pf.tambem_mentor) and pf.nome not ilike '%modelo%'
        and lower(translate(split_part(trim(pf.nome), ' ', 1), 'ÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç', 'AAAAEEIOOOUCaaaaeeiooouc'))
          = lower(translate(x.nome, 'ÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç', 'AAAAEEIOOOUCaaaaeeiooouc'))
     group by x.nome;
  -- "Lu": a mentora com nome começando por Lu que atende o André Decker (Brasdiesel)
  update pl_mapa set perfil_id = (
    select case when count(distinct pf.id) = 1 then (array_agg(distinct pf.id))[1] end
      from perfis pf join mentor_mentorado mm on mm.mentor_id = pf.id join mentorados md on md.id = mm.mentorado_id
     where pf.nome ilike 'lu%' and md.nome ilike '%decker%')
   where nome = 'Lu' and perfil_id is null;

  -- guarda o(s) mentor(es) na avaliação (com o cadastro, quando há)
  update avaliacoes a set extras = a.extras || jsonb_build_object('planilha_mentores', jsonb_build_object(
      'id', p.id, 'encontro', p.cliente || ' · ' || p.programa || ' · ' || p.data_evento,
      'mentores', (select jsonb_agg(m || case when mp.perfil_id is not null then jsonb_build_object('perfil_id', mp.perfil_id) else '{}'::jsonb end)
                     from jsonb_array_elements(p.mentores) m left join pl_mapa mp on mp.nome = m->>'nome')))
    from pl_mentores p where p.aval = a.id;

  -- nota de mentor (1 a 5) para quem tem cadastro
  select p.aval, mp.perfil_id, least(5, greatest(1, ceil((m->>'didatica')::int / 2.0)))::int
    from pl_mentores p cross join lateral jsonb_array_elements(p.mentores) m join pl_mapa mp on mp.nome = m->>'nome'
   where p.aval is not null and mp.perfil_id is not null and m->>'didatica' is not null
  on conflict (avaliacao_id, mentor_id) do nothing;
  get diagnostics n_notas = row_count;

  raise notice 'Pronto: % avaliações ligadas aos mentores (% novas), % notas de mentor novas. Horário: %.', n_ligadas + n_novas, n_novas, n_notas, v_tz;
end $$;

-- conferência: uma linha por mentor (a planilha tem 2.317 avaliações; "sem cadastro" = aparece pelo nome)
select m->>'nome' as mentor, case when m ? 'perfil_id' then 'com cadastro' else 'sem cadastro' end as na_plataforma,
       count(*) as avaliacoes, round(avg((m->>'didatica')::numeric), 1) as didatica_media_0a10
  from avaliacoes a cross join lateral jsonb_array_elements(a.extras->'planilha_mentores'->'mentores') m
 where a.extras ? 'planilha_mentores'
 group by 1, 2
union all
select 'TOTAL de avaliações ligadas', '', count(*), null from avaliacoes where extras ? 'planilha_mentores'
 order by 3 desc;
